import React, { useState, useEffect } from 'react';
import { db } from './firebase';
import { collection, addDoc, getDocs, query, orderBy } from 'firebase/firestore';
import './App.css';

function App() {
  const [posts, setPosts] = useState([]);
  const [newPost, setNewPost] = useState('');
  const [authorName, setAuthorName] = useState('');
  const [loading, setLoading] = useState(false);

  // Fetch posts from Firestore
  const fetchPosts = async () => {
    try {
      console.log('Fetching posts from Firebase...');
      const q = query(collection(db, 'posts'), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      console.log('Found', querySnapshot.size, 'posts');

      const postsData = [];
      querySnapshot.forEach((doc) => {
        postsData.push({ id: doc.id, ...doc.data() });
      });
      setPosts(postsData);
    } catch (error) {
      console.error('Error fetching posts:', error);
      console.error('Error code:', error.code);
      console.error('Error message:', error.message);
    }
  };

  // Add a new post
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!newPost.trim() || !authorName.trim()) {
      alert('Please fill in both fields');
      return;
    }

    setLoading(true);
    try {
      console.log('Attempting to add post...');
      console.log('Author:', authorName);
      console.log('Content:', newPost);
      console.log('Firebase DB:', db);

      // Create a promise that rejects after 10 seconds
      const timeoutPromise = new Promise((_, reject) =>
        setTimeout(() => reject(new Error('Request timed out - check Firebase permissions and that the posts collection exists')), 10000)
      );

      const addPromise = addDoc(collection(db, 'posts'), {
        content: newPost,
        author: authorName,
        createdAt: new Date(),
      });

      const docRef = await Promise.race([addPromise, timeoutPromise]);

      console.log('Post added successfully with ID:', docRef.id);
      alert('Location posted successfully!');
      setNewPost('');
      setAuthorName('');
      await fetchPosts(); // Refresh posts
    } catch (error) {
      console.error('Error adding post:', error);
      console.error('Full error:', JSON.stringify(error));
      alert('Error posting location: ' + error.message + '\n\nMake sure:\n1. Posts collection exists in Firebase\n2. Security rules allow writes\n3. Check browser console for details');
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchPosts();
  }, []);

  return (
    <div className="App">
      <header className="App-header">
        <h1>🩸 Men for Menstruation (Temp)</h1>
        <p>Spreading awareness, easing periods, supporting the girlies</p>
      </header>

      <main className="main-content">
        <section className="about-section">
          <h2>Our Mission</h2>
          <p>
            We're working to normalize conversations about menstruation and ensure 
            everyone has access to period products and education. 
          </p>
        </section>

        <section className="post-form-section">
          <h2>Free Period Product Locations</h2>
          <form onSubmit={handleSubmit} className="post-form">
            <div className="form-group">
              <input
                type="text"
                placeholder="Your name"
                value={authorName}
                onChange={(e) => setAuthorName(e.target.value)}
                className="form-input"
                required
              />
            </div>
            <div className="form-group">
              <textarea
                placeholder="Location Description"
                value={newPost}
                onChange={(e) => setNewPost(e.target.value)}
                className="form-textarea"
                rows="4"
                required
              />
            </div>
            <button 
              type="submit" 
              disabled={loading}
              className="submit-btn"
            >
              {loading ? 'Posting...' : 'Share Post'}
            </button>
          </form>
        </section>

        <section className="posts-section">
          <h2>Community Posts</h2>
          {posts.length === 0 ? (
            <p className="no-posts">No posts yet. Be the first to share!</p>
          ) : (
            <div className="posts-container">
              {posts.map((post) => (
                <div key={post.id} className="post-card">
                  <div className="post-header">
                    <strong>{post.author}</strong>
                    <span className="post-date">
                      {post.createdAt?.toDate?.()?.toLocaleDateString() || 'Recently'}
                    </span>
                  </div>
                  <div className="post-content">
                    {post.content}
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      </main>

      <footer className="App-footer">
        <p>&copy; 2026 Men for Menstruation. Together we can make a difference.</p>
      </footer>
    </div>
  );
}

export default App;
